"""Tracks, lessons, and scenarios. Prose is original study text. Citations point at the source of the facts."""

from tables import TIMELINE

DOC = "https://docs.aws.amazon.com/connect/latest/adminguide/"
API = "https://docs.aws.amazon.com/connect/latest/APIReference/"

def L(id, track, title, why, paras, points, mistake, num, diagram, flow, url, source):
    return {
        "id": id, "track": track, "title": title, "why": why, "paras": paras,
        "points": points, "mistake": mistake, "number": num, "diagram": diagram,
        "flow": flow, "cite": {"url": url, "title": source},
    }

def path(nodes, caption=""):
    return {"type": "path", "nodes": [{"id": str(i), "label": n} for i, n in enumerate(nodes)], "caption": caption}

def layers(nodes, caption=""):
    return {"type": "layers", "nodes": [{"id": str(i), "label": n} for i, n in enumerate(nodes)], "caption": caption}

def split(left, right, caption=""):
    return {"type": "split", "nodes": [{"id": "l", "label": left}, {"id": "r", "label": right}], "caption": caption}

def bars(pairs, caption=""):
    return {"type": "bars", "nodes": [{"id": k, "label": k, "value": v} for k, v in pairs], "caption": caption}

def flow_of(steps):
    return [{"label": a, "detail": b} for a, b in steps]

